# AUTO-GENERATED by Claude Code
# Purpose: "Shelf" look: data first. Every result (from an agent tool or your
#          own Python) is an object on a shelf; pick one to see its widget, where
#          it came from, column stats, and act on it from one command bar.
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

from . import agent_common as ac
from .common import switcher


def _item(name: str, kind: str, source: str, selected: bool = False) -> rx.Component:
    return rx.el.div(
        ac.handle(name),
        rx.el.div(rx.el.div(kind), rx.el.div(source, class_name="dim"), class_name="shelf-meta"),
        class_name="shelf-item" + (" is-selected" if selected else ""),
    )


def _shelf() -> rx.Component:
    return rx.el.div(
        rx.el.div(rx.el.span(ac.ICON_AI, class_name="mono accent-red"), " Pulled by agent", class_name="dock-title"),
        _item("r1", f"framedata · {ac.R1_SHAPE}", "query_smashdb", selected=True),
        _item("c1", "character", "find_character"),
        _item("d1", "doc excerpt", "read_doc"),
        rx.el.div(rx.el.span(ac.ICON_PY, class_name="mono accent-green"), " Made by you", class_name="dock-title"),
        _item("safe", f"DataFrame · {ac.SAFE_SHAPE}", "python, from r1"),
        class_name="shelf sans",
    )


def _stat(name: str, index: int) -> rx.Component:
    numbers = [n for n in (ac._num(r[index]) for r in ac.ROWS) if n is not None]
    span = f"{min(numbers):g} … {max(numbers):g}" if numbers else "text"
    share = len(numbers) / len(ac.ROWS)
    return rx.el.div(
        rx.el.div(rx.el.span(name, class_name="mono"), rx.el.span(span, class_name="dim"), class_name="stat-row"),
        rx.el.div(rx.el.div(class_name="stat-fill", style={"width": f"{share * 100:.0f}%"}), class_name="stat-bar"),
        class_name="stat",
    )


def _inspector() -> rx.Component:
    return rx.el.div(
        rx.el.div("Columns", class_name="dock-title"),
        *[_stat(name, i) for i, (name, _) in enumerate(ac.COLUMNS) if i > 0],
        rx.el.div("bar = share of cells that are plain numbers", class_name="dim stat-note"),
        rx.el.div("Actions", class_name="dock-title"),
        rx.el.button(rx.el.span(ac.ICON_AI, class_name="mono"), " Ask about r1", class_name="act is-wide"),
        rx.el.button(rx.el.span(ac.ICON_PY, class_name="mono"), " Script r1 in Python", class_name="act is-wide"),
        rx.el.button("Derive a new object", class_name="act is-wide"),
        class_name="inspector sans",
    )


def shelf_page() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("reflex-kernel", class_name="title"),
            rx.el.span("4 objects", class_name="dim"),
            class_name="titlebar sans",
        ),
        rx.el.div(
            _shelf(),
            rx.el.div(
                rx.el.div(
                    rx.el.span("“" + ac.QUESTION + "”", class_name="crumb"),
                    rx.el.span("→", class_name="dim"),
                    rx.el.span("query_smashdb", class_name="crumb mono"),
                    rx.el.span("→", class_name="dim"),
                    ac.handle("r1"),
                    rx.el.span("→", class_name="dim"),
                    rx.el.span(ac.handle("safe"), class_name="crumb-next"),
                    class_name="lineage sans",
                ),
                rx.el.div(ac.r1_widget(height=420, actions=False), class_name="shelf-widget"),
                rx.el.div(
                    ac.composer("Do something with r1: ask about it, or r1.filter(…)", ["r1"], active="python"),
                    class_name="shelf-foot",
                ),
                class_name="shelf-center",
            ),
            _inspector(),
            class_name="shelf-main",
        ),
        switcher("shelf"),
        class_name="page shelf-look",
    )
